<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientAuthorizationDetailsTypesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAuthorizationDetailsTypesAccessor trait.
 *
 * Covers null default, string/VO assignment via withAuthorizationDetailsTypes,
 * getAuthorizationDetailsTypes/authorizationDetailsTypes accessors, and isAuthorizationDetailsTypesChanged with/without original.
 */
class TrustedClientAuthorizationDetailsTypesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAuthorizationDetailsTypes creates a new instance with the AuthorizationDetailsTypes set
     * from a string value, and getAuthorizationDetailsTypes returns the primitive string.
     */
    public function testWithAuthorizationDetailsTypesFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAuthorizationDetailsTypesAccessorUnitTest();

        // Act
        $result = $holder->withAuthorizationDetailsTypes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAuthorizationDetailsTypes());
    }
    /**
     * Asserts that withauthorizationDetailsTypes has access to the value object
     * from a string value, and getAuthorizationDetailsTypes returns the primitive string.
     */
    public function testWithAuthorizationDetailsTypesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAuthorizationDetailsTypesAccessorUnitTest();

        // Act
        $result = $holder->withAuthorizationDetailsTypes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->authorizationDetailsTypes()->value());
    }
    public function testChangedAuthorizationDetailsTypes(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAuthorizationDetailsTypesAccessorUnitTest();
        $original = $holder->withAuthorizationDetailsTypes('one');
        $same = $holder->withAuthorizationDetailsTypes('one');
        $modified = $holder->withAuthorizationDetailsTypes('other');

        // Act
        $unchanged = $holder->isAuthorizationDetailsTypesChanged();
        $withSame = $original->isAuthorizationDetailsTypesChanged($same);
        $withDiferent = $original->isAuthorizationDetailsTypesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientAuthorizationDetailsTypesAccessorUnitTest
{
    use TrustedClientAuthorizationDetailsTypesAccessor;
}
